const paths={home:'/',login:'/login',register:'/register',restore:'/restore',overview:'/gov',upload:'/gov/new',paste:'/gov/new/text',documents:'/gov/checks',experts:'/expert', 'expert-done':'/expert/done',profile:'/profile',notifications:'/notifications',methodology:'/help',materials:'/help/materials',quality:'/help/examples',sources:'/sources','source-samples':'/sources/samples','source-materials':'/sources/materials','source-decisions':'/sources/decisions',samples:'/samples',history:'/gov/history','case-history':'/app/case-history',examples:'/help/decisions',privacy:'/privacy',terms:'/terms'};
const sections=new Set(['about','how','features','mission','support','technology','efficiency','practices','become-expert','expert-official-info','contacts']);
export function pathFor(token){if(paths[token])return paths[token];if(sections.has(token))return '/#'+token;const [page,id,n]=token.split('/');if(page==='results')return '/gov/checks/'+id;if(['run','graph','report','run-details','provision'].includes(page))return '/gov/checks/'+id+'/'+({run:'findings',graph:'graph',report:'report','run-details':'details',provision:'points'})[page]+(n!==undefined?'/'+n:'');if(page==='expert-case')return '/expert/review/'+id;if(page==='expert-invite')return '/expert/invite/'+id+'/'+n;if(['prepare','rerun','run-confirm'].includes(page))return '/gov/new/'+id+'/'+n+'/'+page;return '/app/'+token;}
export function tokenFor(value){const u=new URL(value,'https://portal.invalid');if(u.hash)return decodeURIComponent(u.hash.slice(1));const p=u.pathname.replace(/\/$/,'')||'/';for(const [token,path]of Object.entries(paths))if(p===path)return token;let m=p.match(/^\/gov\/checks\/([^/]+)(?:\/(findings|graph|report|details|points)(?:\/([^/]+))?)?$/);if(m)return(m[2]?({findings:'run',graph:'graph',report:'report',details:'run-details',points:'provision'})[m[2]]:'results')+'/'+m[1]+(m[3]?'/'+m[3]:'');m=p.match(/^\/expert\/(review|invite)\/(.+)$/);if(m)return(m[1]==='review'?'expert-case':'expert-invite')+'/'+m[2];m=p.match(/^\/gov\/new\/([^/]+)\/([^/]+)\/(prepare|rerun|run-confirm)$/);if(m)return m[3]+'/'+m[1]+'/'+m[2];return p.startsWith('/app/')?p.slice(5):'not-found';}
export const currentToken=()=>tokenFor(location.href);
export function navigate(token,{replace=false}={}){history[replace?'replaceState':'pushState'](null,'',pathFor(token));window.dispatchEvent(new Event('portalroute'));}
export function canonicalize(){if(location.hash&&!/^#(?:admin\/|delete-personal-key)/.test(location.hash)){const token=currentToken();if(!sections.has(token))history.replaceState(null,'',pathFor(token));}}
export function upgradeLinks(root=document){for(const a of root.querySelectorAll('a[href^="#"]')){const token=a.getAttribute('href').slice(1);if(token==='main-content'||a.dataset.scrollTo)continue;a.setAttribute('href',pathFor(token));}}
